using System;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;using System.Xml;using System.Collections.Generic;using MP1SkinStudio;using MP1SkinStudio.Live;
class StudioProbe{
 static StudioForm form;static StudioLiveClient client;static XmlDocument received;static List<string> results=new List<string>();static object F(string n){return typeof(StudioForm).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);}static void Call(string n,params object[] a){typeof(StudioForm).GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic,null,a.Select(x=>x.GetType()).ToArray(),null).Invoke(form,a);}static void Wait(Func<bool> condition){var t=Stopwatch.StartNew();while(!condition()&&t.ElapsedMilliseconds<20000){Application.DoEvents();Thread.Sleep(20);}if(!condition())throw new Exception("Timeout: "+((Label)F("liveNotice")).Text);}static void Check(bool c,string name){if(!c)throw new Exception(name);results.Add("PASS "+name);Console.WriteLine("PASS "+name);}static XmlDocument Snapshot(){received=null;client.Send(LiveWire.Document("snapshot"));Wait(()=>received!=null);var r=received;Wait(()=>(bool)F("liveVerified"));return r;}static string V(XmlDocument d,int id){return d.SelectSingleNode("/live/control[@id='"+id+"']/value[@key='font']").InnerText;}
 [STAThread]static int Main(string[] args){try{Directory.CreateDirectory(args[2]);Environment.SetEnvironmentVariable("MP1_SKIN_STUDIO_LIVE_DIR",args[1]);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);form=new StudioForm(args[0]);form.Show();form.PrepareExternalPreview(args[0],"studio.live.special.xml","");Call("ConnectLive");Wait(()=>(bool)F("liveVerified"));client=(StudioLiveClient)F("liveClient");client.Response+=d=>{if(d.DocumentElement.GetAttribute("command")=="snapshot")received=d;};var baseline=Snapshot();var p=(SkinProject)F("project");string disk=File.ReadAllText(p.Resolve("fonts.xml"));var selected=p.Controls.First(c=>c.Get("id")=="21203");Call("SelectControl",selected);int before=(int)F("liveRevision");bool shown=false;
 using(var timer=new System.Windows.Forms.Timer{Interval=50}){timer.Tick+=(s,e)=>{var d=Application.OpenForms.OfType<FontDefinitionsDialog>().FirstOrDefault();if(d==null)return;timer.Stop();shown=true;var family=d.Controls.OfType<ChoiceBox>().Single(x=>x.AccessibleName=="Installed font family");family.SelectedIndex=family.FindStringExact("Segoe UI");d.Controls.OfType<NumericUpDown>().Single().Value=26;d.Controls.OfType<CheckBox>().Single(x=>x.Text=="Bold").Checked=true;using(var bitmap=new Bitmap(d.Width,d.Height)){d.DrawToBitmap(bitmap,new Rectangle(0,0,d.Width,d.Height));bitmap.Save(Path.Combine(args[2],"Font-Definitions-Dialog.png"));}d.Controls.OfType<Button>().Single(x=>x.Text=="Apply definition").PerformClick();};timer.Start();Call("EditFontDefinitions");timer.Stop();}
 Wait(()=>(((string)F("liveLastFrame"))??"").Contains(LiveFontDefinition.Prefix)&&(int)F("liveAcknowledged")==((int)F("liveRevision")));var changed=Snapshot();Check(shown&&p.FontSpecs["font18"].Height==26&&p.FontSpecs["font18"].Family=="Segoe UI","Fonts dialog changes family, height and style without XML editing");Check(new[]{21200,21201,21202,21203,21204}.All(id=>V(changed,id).StartsWith("mp1studiofont_")),"one shared definition previews all linked native uses");Check(V(changed,21205)==V(baseline,21205),"unrelated font aliases remain unchanged");Check(changed.DocumentElement.GetAttribute("epoch")==baseline.DocumentElement.GetAttribute("epoch"),"font definition updates do not reload the MP page");Check(File.ReadAllText(p.Resolve("fonts.xml"))==disk&&p.Dirty,"font definitions stay in the editor model until explicitly saved");string project=Path.Combine(args[2],"font-preview.mp1skinproj");ProjectFile.Save(p,project);var reopened=ProjectFile.Load(project);Check(reopened.FontSpecs["font18"].Height==26&&reopened.FontSpecs["font18"].Family=="Segoe UI","project save/reopen retains changed fonts.xml definitions");
 before=(int)F("liveRevision");Call("UndoEditor",false);Wait(()=>!(((string)F("liveLastFrame"))??LiveFontDefinition.Prefix).Contains(LiveFontDefinition.Prefix)&&(int)F("liveAcknowledged")==((int)F("liveRevision")));var restored=Snapshot();Check(new[]{21200,21201,21202,21203,21204}.All(id=>V(restored,id)==V(baseline,id)),"Undo restores native font aliases across all linked controls");Check(!p.Dirty&&File.ReadAllText(p.Resolve("fonts.xml"))==disk,"Undo retains exact original source state");Call("DisconnectLive");Wait(()=>F("liveClient")==null);Console.WriteLine(results.Count+" font Studio workflow checks passed.");return 0;}catch(Exception ex){results.Add(ex.ToString());Console.Error.WriteLine(ex);return 1;}finally{if(form!=null)form.Dispose();Directory.CreateDirectory(args[2]);File.WriteAllLines(Path.Combine(args[2],"Results.txt"),results);}}
}
